using System;
namespace gazegallery;
public static class ExtendedAdjustments {
 public static byte[] Apply(byte[] pixels,int width,int height,double[] v){if(System.Linq.Enumerable.All(System.Linq.Enumerable.Skip(v,12),n=>n==0))return pixels;double redScale=Math.Pow(2,v[20]/100),greenScale=Math.Pow(2,v[21]/100),blueScale=Math.Pow(2,v[22]/100);double hue=v[12]*Math.PI/100,gamma=Math.Pow(2,v[13]/100),cos=Math.Cos(hue),sin=Math.Sin(hue);for(int i=0;i<pixels.Length;i+=4){double r=pixels[i+2]/255d,g=pixels[i+1]/255d,b=pixels[i]/255d;if(v[12]!=0){double y=.299*r+.587*g+.114*b,u=.596*r-.274*g-.322*b,w=.211*r-.523*g+.312*b,nu=u*cos-w*sin,nw=u*sin+w*cos;r=y+.956*nu+.621*nw;g=y-.272*nu-.647*nw;b=y-1.106*nu+1.703*nw;}r=Math.Clamp(r,0,1);g=Math.Clamp(g,0,1);b=Math.Clamp(b,0,1);if(v[13]!=0){r=Math.Pow(r,1/gamma);g=Math.Pow(g,1/gamma);b=Math.Pow(b,1/gamma);}r=Math.Clamp(r*redScale,0,1);g=Math.Clamp(g*greenScale,0,1);b=Math.Clamp(b*blueScale,0,1);if(v[23]!=0)r=1-r;if(v[24]!=0)g=1-g;if(v[25]!=0)b=1-b;if(v[14]!=0){r=g=b=.2126*r+.7152*g+.0722*b;}if(v[15]!=0){r=1-r;g=1-g;b=1-b;}if(v.Length>27){double amount=v[26]/100;if(amount>0){double sr=Math.Min(1,.393*r+.769*g+.189*b),sg=Math.Min(1,.349*r+.686*g+.168*b),sb=Math.Min(1,.272*r+.534*g+.131*b);r+=(sr-r)*amount;g+=(sg-g)*amount;b+=(sb-b)*amount;}if(v[27]>0){int levels=Math.Max(2,256-(int)Math.Round(v[27]*254/100));r=Math.Round(r*(levels-1))/(levels-1);g=Math.Round(g*(levels-1))/(levels-1);b=Math.Round(b*(levels-1))/(levels-1);}}if(v[16]!=0){r=g=b=(.2126*r+.7152*g+.0722*b)>=(v[17]+100)/200?1:0;}pixels[i]=(byte)Math.Round(b*255);pixels[i+1]=(byte)Math.Round(g*255);pixels[i+2]=(byte)Math.Round(r*255);}int radius=(int)Math.Round(v[18]);if(radius>0){if((int)v[19]==2)return Motion(pixels,width,height,v.Length>29&&v[29]>0?v[29]*v[18]/25:radius*2,v.Length>28?v[28]:0);if((int)v[19]==1)return Box(pixels,width,height,radius,false);int r=(int)Math.Round(Math.Pow(v[18]/50,2)*12);if(r>0)for(int n=0;n<3;n++)pixels=Box(pixels,width,height,r,false);}return pixels;}
 public static byte[] Motion(byte[] input,int w,int h,double length,double degrees){int samples=Math.Clamp((int)Math.Ceiling(length)+1,2,33);double angle=degrees*Math.PI/180,dx=Math.Cos(angle)*length,dy=Math.Sin(angle)*length;var output=new byte[input.Length];System.Threading.Tasks.Parallel.For(0,h,new System.Threading.Tasks.ParallelOptions{MaxDegreeOfParallelism=LoaderPool.Limit},y=>{for(int x=0;x<w;x++){double r=0,g=0,b=0,a=0;for(int n=0;n<samples;n++){double t=n/(double)(samples-1)-.5,px=Math.Clamp(x+dx*t,0,w-1),py=Math.Clamp(y+dy*t,0,h-1);int ix=(int)px,iy=(int)py,nx=Math.Min(w-1,ix+1),ny=Math.Min(h-1,iy+1);double fx=px-ix,fy=py-iy;void Add(int sx,int sy,double weight){int p=(sy*w+sx)*4;double alpha=input[p+3]*weight;a+=alpha;r+=input[p+2]*alpha;g+=input[p+1]*alpha;b+=input[p]*alpha;}Add(ix,iy,(1-fx)*(1-fy));Add(nx,iy,fx*(1-fy));Add(ix,ny,(1-fx)*fy);Add(nx,ny,fx*fy);}int i=(y*w+x)*4;output[i]=a==0?(byte)0:(byte)Math.Clamp(Math.Round(b/a),0,255);output[i+1]=a==0?(byte)0:(byte)Math.Clamp(Math.Round(g/a),0,255);output[i+2]=a==0?(byte)0:(byte)Math.Clamp(Math.Round(r/a),0,255);output[i+3]=(byte)Math.Clamp(Math.Round(a/samples),0,255);}});return output;}
 // Sliding sums make blur linear in pixel count, independent of the radius.
 public static byte[] Box(byte[] input,int w,int h,int radius,bool horizontalOnly){var tmp=new byte[input.Length];var output=new byte[input.Length];for(int y=0;y<h;y++){long[] sum=new long[4];int right=-1,left=0;for(int x=0;x<w;x++){int end=Math.Min(w-1,x+radius);while(right<end){right++;for(int c=0;c<4;c++)sum[c]+=input[(y*w+right)*4+c];}int start=Math.Max(0,x-radius);while(left<start){for(int c=0;c<4;c++)sum[c]-=input[(y*w+left)*4+c];left++;}for(int c=0;c<4;c++)tmp[(y*w+x)*4+c]=(byte)(sum[c]/(right-left+1));}}if(horizontalOnly)return tmp;for(int x=0;x<w;x++){long[] sum=new long[4];int bottom=-1,top=0;for(int y=0;y<h;y++){int end=Math.Min(h-1,y+radius);while(bottom<end){bottom++;for(int c=0;c<4;c++)sum[c]+=tmp[(bottom*w+x)*4+c];}int start=Math.Max(0,y-radius);while(top<start){for(int c=0;c<4;c++)sum[c]-=tmp[(top*w+x)*4+c];top++;}for(int c=0;c<4;c++)output[(y*w+x)*4+c]=(byte)(sum[c]/(bottom-top+1));}}return output;}
}
